class View:
    def __init__(self):
        self.rows=[]; self.notes={}; self.loading=False; self.error=None
        self._seq=0

    def begin(self, query):
        self._seq+=1
        self.loading=True
        self.error=None  # begin clears any loading errors
        # existing rows are kept until a valid finish
        return self._seq

    def finish(self, request_id, rows):
        # only the latest begun request may update rows, and only once
        if request_id != self._seq:
            return False
        if not self.loading:
            return False  # duplicate reply for an already-finished request
        if rows is None:
            rows=[]
        self.rows=list(rows)  # copy accepted rows
        self.loading=False
        # notes (job_id -> note) are preserved through all requests
        return True

